function applyPortfolioCaseReview(data){
 if(data._portfolioCaseReviewVersion>=1||!(data._skillsOrganisationVersion>=1))return;
 const all=data.categories.flatMap(c=>c.skills);
 const additions=[['product-definition','Product definition'],['information-architecture','Information architecture'],['content-design','Content design'],['technical-specification','Technical specification'],['usability-iteration','Usability review and iteration'],['accessibility-design','Accessibility considerations']];
 for(const [id,label]of additions)if(!all.some(s=>s.id===id))all.push({id,label,role:'',article:'a'});
 const structure=[
 ['design','Design',[
 ['Direction and concepts',['creative-direction','concept-development','art-direction','product-definition']],
 ['Experience and information',['ui-ux','interaction-design','information-architecture','accessibility-design','usability-iteration']],
 ['Game worlds and systems',['game-design-practice','level-design','environment-design','environmental-storytelling','systems-design','progression-design','playtesting']],
 ['Story and content',['narrative-design','story','content-design']]]],
 ['development','Development',[
 ['Unreal Engine and gameplay',['unreal-engine','blueprints','gameplay-programming','gameplay-prototyping','ai-navigation','dialogue-systems']],
 ['Interfaces and integration',['ui-implementation','asset-integration','api-integration']],
 ['Python tools and data',['python','desktop-tools','procedural-generation','data-persistence']],
 ['Technical planning and delivery',['technical-specification','release-support']]]],
 ['production','Production & collaboration',[
 ['Project delivery',['film-producing','project-management','scope-delivery']],
 ['Planning and resources',['production-planning','production-scheduling','budgeting','location-scouting']],
 ['People and handovers',['team-coordination','casting','post-production-coordination']],
 ['Documentation',['design-documentation']]]],
 ['art-media','Visual art & animation',[
 ['Illustration and composition',['digital-illustration','character-illustration','poster-design','visual-composition','colour-design']],
 ['3D scenes',['3d-rendering','lighting']],
 ['Animation',['2d-animation','character-animation','animation-timing','squash-stretch']]]],
 ['film-audio','Film & audio',[
 ['Direction and camera',['directing','camera-operation','camera-movement']],
 ['Editing',['editing','assistant-editing']],
 ['Sound and music',['sound-design','music-composition','production-sound']],
 ['Interactive audio',['procedural-audio','audio-implementation','adaptive-audio']]]]
 ];
 const assigned=new Set();const categories=structure.map(([id,label,rows])=>({id,label,role:'',article:'a',skills:rows.flatMap(([displayGroup,ids])=>ids.map(id=>all.find(s=>s.id===id)).filter(Boolean).map(skill=>{assigned.add(skill.id);return {...skill,displayGroup}}))}));
 for(const old of data.categories){const extra=old.skills.filter(s=>!assigned.has(s.id));if(extra.length){const target=categories.find(c=>c.id===old.id);if(target)target.skills.push(...extra);else categories.push({...old,skills:extra});}}
 data.categories=categories;
 // Remove unsupported inherited assignments, not the owner's confirmed film-production work.
 const uncertain={'solar-trash':['procedural-generation','art-direction','design-documentation','ui-implementation','dialogue-systems','audio-implementation','adaptive-audio'],'perhaps':['assistant-editing'],'oh-what-a-night':['camera-movement']};
 for(const [id,ids]of Object.entries(uncertain)){const project=data.projects.find(p=>p.id===id);if(project){project.evidenceReview={date:'2026-10-27',pendingConfirmation:ids.filter(x=>project.skillIds?.includes(x)),note:'Inherited assignments not established by the accessible project credits. May be restored after confirmation.'};project.skillIds=(project.skillIds||[]).filter(x=>!ids.includes(x));}}
 if(!data.projects.some(p=>p.id===portfolioCaseStudy.id)){
  const project=structuredClone(portfolioCaseStudy);
  project.groupId=data.groups?.find(g=>g.id==='creative-coding'||g.id==='coding')?.id||'';
  let slug=project.slug;while(data.projects.some(p=>p.slug===slug))slug+='-case';project.slug=slug;
  data.projects.push(project);
 }
 if(data.copy.skillsIntro==='Each dot links to a project where I used that skill. Hover or focus for its name.')data.copy.skillsIntro='Browse by the kind of work you need. Each dot opens a project that demonstrates the skills in that row. Dots are examples, not proficiency ratings. Hover or focus for the project and skills.';
 data._portfolioCaseReviewVersion=1;
}

const portfolioPresentation={"id": "portfolio-studio-desk", "slug": "portfolio-studio-desk", "title": "Portfolio & Studio Desk", "groupId": "creative-coding", "description": "The portfolio you’re browsing, plus a custom editor for writing, organising and publishing it.", "tagline": "This website, and the custom editor that keeps it growing.", "summary": "You are using one half of this project right now: a portfolio that connects my games, films, artwork and software to the skills behind them. The other half is Studio Desk, a custom browser-based editor we built for this website. It lets me write project pages, arrange content, manage images, preview changes and publish through GitHub without editing the site’s code for each update.", "banner": "assets/case-study/home.jpg", "bannerAlt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "featured": false, "status": "published", "pageEnabled": true, "externalUrl": "", "playUrl": "", "playLabel": "Explore the portfolio", "gameplay": {"type": "video", "src": "", "alt": "", "caption": "", "placeholder": ""}, "sections": [{"id": "what-it-is", "heading": "What it is", "label": "What it is", "sidebar": true, "skills": ["product-definition", "information-architecture"], "blocks": [{"id": "portfolio-what-it-is", "type": "text", "text": "This is a case study of the website you are browsing. There are two connected products here: the public portfolio and the editor used to maintain it. They were developed together because I wanted both the experience of presenting my work and the experience of updating it to make sense.\n\nThe public side has a homepage, a Work collection, a Skills index, a Contact page and individual project stories like this one. You can start with a project that catches your eye, or start with a skill and follow its dots to examples. Games, films and illustrations can sit together without needing to pretend they are the same kind of work.\n\nStudio Desk is the name we gave the custom editor. It is not an existing service I signed up for, and it is not something a visitor needs to install. It is a separate editing screen for this portfolio, opened in a browser. Think of it as the control room: I can add a project, write sections, upload media, move blocks around and see the result before publishing.\n\nA typical update looks like this: open Studio Desk, edit a draft, check the live preview, then publish when it is ready. The draft and the public website are separate, so trying a new paragraph or colour does not immediately change what a visitor sees. That freedom to keep experimenting is a big part of why I wanted to build it."}]}, {"id": "starting-point", "heading": "How it started", "label": "How it started", "sidebar": true, "skills": ["concept-development", "creative-direction"], "blocks": [{"id": "portfolio-starting-point-text", "type": "text", "text": "I find it difficult to pitch myself. I have worked on games, films, illustrations, animations and software, but I struggle to fit all of that into one title. Sometimes calling myself a designer feels too broad. Calling myself a developer leaves out the production and visual work. Listing everything can sound like I am trying to be everything at once.\n\nImposter syndrome is part of that. It is easier for me to talk about something I made than to stand in front of someone and announce what I am good at. I wanted a portfolio that could help with that conversation, but I also wanted a way to understand the work for myself.\n\nThe starting point was a collection of links on my bio site. That gave people somewhere to find things, but it did not explain how the projects connected, what I contributed or why I made particular decisions. This website became an attempt to answer those questions."}]}, {"id": "brief", "heading": "What the website needed to do", "label": "What the website needed to do", "sidebar": true, "skills": ["product-definition", "scope-delivery"], "blocks": [{"id": "portfolio-brief-text", "type": "text", "text": "The starting brief was simple to say and surprisingly demanding to deliver: make my work understandable, make the website feel like mine and let me keep updating it myself.\n\nFor a visitor, that meant clear routes into the projects, descriptions of my contributions and a layout that works on a phone as well as a desktop. A recruiter should be able to scan the work quickly. Someone interested in how a project was made should be able to stay and read the detail. Neither should have to know my history before the page makes sense.\n\nFor me, it meant control over the content after the website was built. I wanted to change a heading, add an image in the middle of a write-up, rearrange sections, update skills and change colours without reopening the source code every time. Those requirements grew into Studio Desk.\n\nThere were practical constraints too. The GitHub version needed to work without a server I had to maintain or another paid hosting subscription. I also wanted to decide when the portfolio was public, while still being able to edit it. Suddenly this was more than choosing a homepage layout. It was a small publishing system, with a public experience and an editing experience that both needed to work."}]}, {"id": "evidence", "heading": "Projects as evidence", "label": "Projects as evidence", "sidebar": true, "skills": ["information-architecture", "ui-ux"], "blocks": [{"id": "portfolio-evidence-text", "type": "text", "text": "The organising idea was that projects could provide evidence for skills. Someone interested in a particular capability should be able to follow it to a real piece of work, rather than take a rating or a progress bar at face value.\n\nThat led to two main ways of browsing. Work groups projects by medium. Skills groups the kinds of work I have done and links them back to those projects. A game can support design, programming and production skills without needing to appear as three separate projects.\n\nThe dots on the Skills page are links, not scores. More dots mean more linked examples, not a measured level of expertise. Hovering or focusing a dot reveals the project name. The accessible link label also describes the skills represented by that project. Where there is a case study, the link can lead to the relevant section. Where there is not, it leads directly to the external project."}, {"id": "portfolio-skills-screenshot", "type": "image", "src": "assets/case-study/skills-iteration.jpg", "alt": "An earlier Skills page showing grouped skill labels with project evidence dots.", "caption": "An earlier live iteration of Skills. The project dots established the browsing model; the categories were later consolidated to make it easier to scan."}]}, {"id": "identity", "heading": "An introduction without one fixed title", "label": "An introduction without one fixed title", "sidebar": true, "skills": ["interaction-design", "content-design"], "blocks": [{"id": "portfolio-identity-text", "type": "text", "text": "The rotating introduction came from the same difficulty with labels. I did not want the first sentence to reduce everything to one role, but I also did not want an overwhelming list of titles above the work.\n\nThe roles are drawn from the skills data. Their likelihood is weighted by linked evidence, so the introduction is connected to the portfolio rather than being an unrelated animation. That weighting is a browsing choice, not a scientific assessment of what I am best at.\n\nI asked for pause controls, manual previous and next arrows and links from each role to its place on the Skills page. I also revised titles that felt vague or inflated. For example, a title like Creative Technologist did not explain the specific Python work it linked to. The goal was to make the language easier to understand, not more impressive."}]}, {"id": "visual-language", "heading": "Choosing the visual language", "label": "Choosing the visual language", "sidebar": true, "skills": ["art-direction", "ui-ux"], "blocks": [{"id": "portfolio-visual-language-text", "type": "text", "text": "The visual direction uses a grid, strong type, restrained borders and small accent details. I wanted the projects to feel connected even though they come from different media. The interface needed enough personality to feel like mine without competing with the work.\n\nLight and dark themes share a palette system. Studio Desk offers preset combinations and individual colour controls, along with the ability to remove presets I do not want. The palette became part of the editing experience rather than a permanent choice buried in a stylesheet.\n\nWe revised prominence through feedback. A stronger highlight on Selected projects felt too loud, so I asked to revert it. The accent highlight moved to a smaller View all work link at the end of the section. Its bounding box and arrow were removed. That gave the invitation to continue browsing more emphasis without making the whole section shout."}]}, {"id": "portrait", "heading": "Making the portrait feel responsive", "label": "Making the portrait feel responsive", "sidebar": true, "skills": ["interaction-design", "usability-iteration"], "blocks": [{"id": "portfolio-portrait-text", "type": "text", "text": "The portrait started as an initials card. I liked the AS treatment and did not want to lose it when adding a photograph, so the idea became a two-sided card rotating around its vertical axis.\n\nThe first interactions were not right. A simple hover flip was too predictable, while repeated spinning could be distracting or feel too fast. I compared the feel I wanted to a coin that responds to a swipe: direction and speed should matter, and a new gesture should be able to interrupt the existing spin.\n\nThe interaction changed several times. The image became the first face. A click flips once. Pressing on the card and dragging gives direct control, while a held mouse sweep can start outside the card and flick it as it crosses. Ordinary hovering no longer starts a spin. Reduced-motion preferences bypass the animated momentum.\n\nA later issue was text selection competing with the gesture. Disabling selection on the public page removed that interference, but it also makes copying ordinary page text harder. That is a trade-off I would revisit by limiting selection suppression to active gestures. The editor keeps normal text selection."}]}, {"id": "navigation", "heading": "Fixing the Work menu", "label": "Fixing the Work menu", "sidebar": true, "skills": ["information-architecture", "interaction-design", "usability-iteration"], "blocks": [{"id": "portfolio-navigation-text", "type": "text", "text": "The Work menu exposed a problem that was easy to miss when looking at a still image. Expanding Games pushed the categories below it down. When the pointer moved towards Film, Games collapsed and those targets moved back up underneath the pointer. A visitor could end up on a different category without intending to.\n\nKeeping every visited category open stopped that movement, but introduced another problem: the menu grew until it needed its own scroll area. That was not the interaction I wanted either.\n\nThe next approach kept the category positions fixed and opened project links in a side panel. Hovering Work shows only the categories. Hovering a category opens its panel, with a short animation when it opens and closes. The panel can change side when it needs room near the viewport edge. Long categories show a limited set of projects and a link to the full category instead of a long scrolling menu.\n\nClick and keyboard controls remain available. Closing panels become non-interactive while they animate away, and interrupted animations cannot close a panel that has already reopened. Those details matter because the menu needs to remain usable when someone moves faster than the animation."}]}, {"id": "case-studies", "heading": "Giving the work a readable structure", "label": "Giving the work a readable structure", "sidebar": true, "skills": ["content-design", "information-architecture"], "blocks": [{"id": "portfolio-case-studies-text", "type": "text", "text": "NightShift established the project-page structure: title, short tagline, media when useful, summary and a longer write-up with section links. The write-up explains the initial idea, decisions, implementation, reflection and what I would change. Role, tools and release information belong near the end rather than interrupting the opening explanation.\n\nThe section-link labels should match the headings they lead to. On smaller screens, those links wrap naturally across rows instead of becoming an awkward two-column sidebar. The same structure is used here, with the amount of detail adapted to this project.\n\nI originally wanted visitors to stay inside the portfolio, but writing a dedicated page for every piece would delay getting the existing work in front of people. The interim decision was to link most projects directly to where they could be viewed. That keeps the work accessible while case studies are added gradually."}]}, {"id": "studio-desk", "heading": "Why Studio Desk became part of the project", "label": "Why Studio Desk became part of the project", "sidebar": true, "skills": ["product-definition", "content-design", "systems-design"], "blocks": [{"id": "portfolio-studio-desk-text", "type": "text", "text": "Studio Desk is where the portfolio becomes something I can keep using. Instead of asking me to edit HTML files, it presents the content as projects, sections and blocks. The name came from needing an easy way to refer to the editor while building it. The software itself was made for this site.\n\nA project starts with its title, description, group and destination. It can link to a game on itch, a film elsewhere or a full case study inside the portfolio. A dedicated page can be prepared while its public links still point to an external destination. That is how NightShift can keep sending visitors to the playable game while I work on its longer write-up.\n\nInside a case study, I can add sections, choose their headings and decide which ones appear in the contents navigation. Blocks provide text, images, GIFs, video, quotes, galleries and layouts with media beside text. They can be inserted between existing blocks, moved and resized. The title, summary, project details and ending links are reusable page components, which keeps the structure consistent without freezing the arrangement.\n\nThe editor also manages the connections that make the portfolio useful. I can assign skills to a project or a particular section, choose featured work, organise project groups and edit shared labels. Contact links and hover messages are editable. So are the palettes and the timing of the rotating roles.\n\nThat is the part I am particularly pleased with: the site does not have to remain the exact collection of pages it was on launch day. Adding the next piece of work is part of the product, rather than another website-building project."}, {"id": "portfolio-editor-screenshot", "type": "image", "src": "assets/case-study/studio-desk.jpg", "alt": "Studio Desk with page controls on the left, editable homepage content in the centre and the rendered portfolio preview on the right.", "caption": "Studio Desk in a read-only local demonstration: content controls and the rendered page sit side by side. This screenshot does not show a connected GitHub session."}]}, {"id": "preview", "heading": "Getting the preview out of the way", "label": "Getting the preview out of the way", "sidebar": true, "skills": ["usability-iteration", "interaction-design"], "blocks": [{"id": "portfolio-preview-text", "type": "text", "text": "A useful editor needs a good feedback loop. If I change a colour or move a block, I want to see what happened while the decision is still fresh. That became one of the most important parts of Studio Desk.\n\nThe preview initially swung between two frustrating extremes. Frequent refreshes felt disruptive, while manual refreshes made even small changes feel disconnected from their result. The current approach waits briefly after an edit, then updates automatically. It remembers the page scroll position and the chosen light or dark theme, so I can keep looking at the same part of the page as I work.\n\nDesktop and mobile preview sizes help me compare how the layout responds. Changing a palette is particularly useful this way: I can see it across the actual page instead of trying to imagine a website from three colour swatches.\n\nTechnically, the preview runs in a sandboxed iframe, a separate document inside the editor. Styles, scripts and media are supplied so it can render without relying on an authenticated request for every asset. The interaction script runs after the document content exists. Messages between the preview and editor keep track of scroll and theme state, while a version check prevents an older render response from replacing a more recent edit. Each of those details supports the same goal: let me stay focused on the thing I am changing."}]}, {"id": "implementation", "heading": "How the implementation is organised", "label": "How the implementation is organised", "sidebar": true, "skills": ["systems-design", "technical-specification"], "blocks": [{"id": "portfolio-implementation-text", "type": "text", "text": "The public site is built with HTML, CSS and JavaScript. HTML gives the pages their structure, CSS handles the visual system and responsive layouts, and JavaScript adds behaviours such as the rotating introduction, project menus, theme switch and portrait interaction. There is no React-style component framework required to display the portfolio.\n\nThe content lives in structured data rather than being scattered through individual page files. A project contains its description, sections, blocks, skills and publication settings. Rendering functions turn that data into HTML. This makes a project reusable in several places: the same record can supply its Work card, featured card, menu entry, skill links and detailed page.\n\nThe page builder uses that same idea at a smaller scale. A text block, image block or gallery has its own content and layout settings. The renderer knows how to display each type. This is what makes moving an image between paragraphs or rearranging the introduction possible without rewriting the page template.\n\nThe renderer is shared by preview and export. The editor is not maintaining a separate imitation of the page; it uses the same rendering logic that prepares the published output. Node.js build scripts package the templates, public assets and editor distribution. Versioned asset URLs help updated editor files load together rather than mixing a cached old script with a new interface.\n\nThe implementation also handles the small details that make a static site practical: project links are converted into clean page routes, relevant media files are collected for publication, draft-only pages are excluded and relative paths can accommodate a GitHub project subdirectory. The result is ordinary website files that can be served by GitHub Pages, with the richer editing behaviour living in the browser."}]}, {"id": "publishing", "heading": "Separating editing from publishing", "label": "Separating editing from publishing", "sidebar": true, "skills": ["systems-design", "product-definition"], "blocks": [{"id": "portfolio-publishing-text", "type": "text", "text": "GitHub Pages serves the public portfolio as static files. Studio Desk supplies the editing and publishing workflow that sits in front of those files. It talks to GitHub through its API, the interface that lets software read and update repository content.\n\nThere are two repositories in the workflow. The private repository holds the draft, uploaded files and history. The public Pages repository holds the website that visitors can see. Publishing renders the selected content, gathers the media it needs and updates the public files. Saving a draft is a separate action, so unfinished writing can stay private.\n\nThe publishing screen distinguishes a current live site from one with unpublished changes. It can also take the public portfolio offline while retaining access to Studio Desk. That replaces the public pages with an unavailable screen; previously public files can still exist in caches or repository history.\n\nThere is also an editor-only update. This refreshes Studio Desk itself while preserving the portfolio’s current publication state. That distinction was essential while the tool was being developed: improving the editor should not unexpectedly publish a new paragraph or switch the portfolio online.\n\nThe original setup environment uses a Worker and object storage, but the GitHub edition does not require that server for everyday editing and publishing. Its editor runs in the browser, the content lives in GitHub and Pages serves the output. A short deployment delay was an acceptable trade-off for having a workflow I could use independently."}]}, {"id": "access", "heading": "Access and saved connections", "label": "Access and saved connections", "sidebar": true, "skills": ["technical-specification", "interaction-design"], "blocks": [{"id": "portfolio-access-text", "type": "text", "text": "The editor connects using a GitHub access token with access to the relevant repositories. A secret-looking editor URL is not the security boundary; repository permissions and the token are what control access to the private content and publishing operations.\n\nTyping the token every time was inconvenient, so an optional local unlock password was added. The password encrypts the saved token in that browser using browser cryptography. It is not a separate account service or a replacement for GitHub permissions. An expired token still has to be replaced.\n\nThe choice to remember the connection is optional, which matters on shared or work computers. The editor can also clear the connection. These are usability decisions around an existing credential, not a claim that the project provides a fully audited authentication platform."}]}, {"id": "draft-conflicts", "heading": "Protecting edits when drafts disagree", "label": "Protecting edits when drafts disagree", "sidebar": true, "skills": ["systems-design", "usability-iteration"], "blocks": [{"id": "portfolio-draft-conflicts-text", "type": "text", "text": "One of the less visible features became one of the most valuable: protecting text when two versions of a draft disagree. Imagine leaving Studio Desk open on one computer, making a change elsewhere, then returning to the first tab. That tab is now editing an older version.\n\nThe save process compares three things: the draft the tab started from, the local edits and the latest draft on GitHub. If the changes affect different fields, they can be combined. If both versions changed the same field, the editor asks which version to keep. It also preserves recovery copies instead of silently throwing one away.\n\nThere is another race to handle while a save is in progress. If I keep typing before the response comes back, the newly typed text must not be overwritten by the result of the earlier save. The editor keeps those newer changes pending for the next save. Downloadable backups provide an additional route out of a problem.\n\nIt is easy to describe a content editor as a set of text boxes and a Publish button. This part of the project showed how much care sits behind those controls. The editor needs to protect the work while making the state of that work understandable."}]}, {"id": "feedback", "heading": "What feedback changed", "label": "What feedback changed", "sidebar": true, "skills": ["usability-iteration", "production-planning"], "blocks": [{"id": "portfolio-feedback-text", "type": "text", "text": "A conversation with my WorkBC recruiter led to another round of revisions. The photograph needed to appear first. Hovering across the homepage should not accidentally spin the portrait. There needed to be a clearer route from featured projects to the full collection. Contact information needed its own page as well as a place in the footer.\n\nThe Contact page then changed again. Separating email from social links felt unnecessarily rigid, so the links became one column of matching cards. The cards can show a short invitation on hover or keyboard focus, and those messages can be edited in Studio Desk. The text transition was shortened when it felt sluggish.\n\nThis was informal feedback and repeated use, not a formal usability study. It identified specific problems and helped me change the design, but it does not establish that the site works equally well for every visitor. I have no measured recruitment conversion or time-saving result to attach to it."}]}, {"id": "accessibility", "heading": "Accessibility and the remaining trade-offs", "label": "Accessibility and the remaining trade-offs", "sidebar": true, "skills": ["accessibility-design", "usability-iteration"], "blocks": [{"id": "portfolio-accessibility-text", "type": "text", "text": "The site includes keyboard focus treatments, a skip link, labelled controls, project-name tooltips available on focus, reduced-motion support and responsive layouts. The role animation can be paused. Touch interaction is considered separately from hover, particularly for the portrait and navigation.\n\nThat does not mean the work is finished or that the site has been certified against an accessibility standard. Functional checks cover specific behaviours. They do not replace testing with assistive technology or observing people using the site.\n\nOne unresolved decision is colour contrast. The palette originally adjusted accent text for each background. I preferred the consistency of using the exact same accent in both themes, so that adjustment was removed. Bright accents can be difficult to read on light backgrounds, and white text on a bright accent button can also be weak. A stronger next iteration would preserve the accent for decorative elements and define accessible foreground/background pairings for text and controls.\n\nI also want to revisit page-wide text-selection suppression, test the menus at high zoom and check the full editing and publishing journey with keyboard and screen-reader users. These are specific improvements to work towards, not features I am claiming are already solved."}]}, {"id": "my-contribution", "heading": "My role and the implementation process", "label": "My role and the implementation process", "sidebar": true, "skills": ["creative-direction", "technical-specification"], "blocks": [{"id": "portfolio-my-contribution-text", "type": "text", "text": "I defined the problem, set the constraints and directed the product through repeated rounds of feedback. The evidence-based Skills page, rotating introduction, project-page structure and requirement for an independently usable editor came out of those decisions.\n\nImplementation was AI-assisted. I used that support to develop the code, investigate problems and iterate on the site and editor. My contribution centred on product definition, creative direction, information architecture, interaction decisions, content and testing through use.\n\nWhat I want this project to show is the process behind the experience: noticing what is confusing, being specific about what should change and following the consequences of those choices all the way through the product."}]}, {"id": "reflection", "heading": "What I learned and what comes next", "label": "What I learned and what comes next", "sidebar": true, "skills": ["scope-delivery", "content-design"], "blocks": [{"id": "portfolio-reflection-text", "type": "text", "text": "The project started as a way to show my work and became a way to understand it. Having to connect a skill to a project forced me to be more specific about what I had done. It also made it easier to see where I was relying on a vague label or borrowing credit from a team outcome.\n\nThere is a similar lesson in the interface. A spinning card can look good and still interrupt the visitor. A dropdown can look tidy until the targets move under the pointer. A preview can be technically working and still make editing frustrating. The revisions often came from noticing that difference.\n\nIf I were starting again, I would settle the content structure and the editor/publication boundary earlier. I would also put more deliberate limits on custom interactions until the basic browsing and editing flows were tested. The site has accumulated revisions, and simplifying the implementation is part of keeping it maintainable.\n\nThe next steps are to write more project case studies, improve contrast without losing the visual identity, test accessibility more systematically and keep checking whether the Skills page helps someone find relevant work quickly. I still find it difficult to put one label on myself. The difference is that I now have a clearer way to show what sits behind those labels."}]}], "credits": [], "facts": [{"label": "My work", "value": "Product direction, experience design, information architecture, writing and iterative testing"}, {"label": "Implementation", "value": "Custom HTML, CSS and JavaScript · browser-based editing · GitHub API · static GitHub Pages publishing"}, {"label": "Project status", "value": "Working portfolio and editor · continuing to refine the experience and add project stories"}], "introBlocks": [{"id": "portfolio-projectTitle", "type": "projectTitle"}, {"id": "portfolio-overview-screenshot", "type": "image", "src": "assets/case-study/home.jpg", "alt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "caption": "The live homepage, captured during development. The introduction links roles to the work behind them."}, {"id": "portfolio-projectTagline", "type": "projectTagline"}, {"id": "portfolio-projectSummary", "type": "projectSummary"}, {"id": "portfolio-facts", "type": "facts"}], "endBlocks": [{"id": "portfolio-endLinks", "type": "endLinks"}]};
function applyPortfolioPresentation(data){
 if(data._portfolioPresentationVersion>=1||!(data._portfolioCaseReviewVersion>=1))return;
 const night=data.projects.find(p=>p.id==='nightshift');if(night){night.publicDestination='external';night.externalUrl=night.playUrl||'https://downloadingmedia.itch.io/nightshift-alpha';}
 const p=data.projects.find(p=>p.id==='portfolio-studio-desk');if(p){for(const key of ['tagline','summary','description','banner','bannerAlt','introBlocks','endBlocks','facts','sections'])p[key]=structuredClone(portfolioPresentation[key]);}
 for(const project of data.projects)project.featured=['nightshift','daisychain','portfolio-studio-desk'].includes(project.id);
 data._portfolioPresentationVersion=1;
}

function applyProjectOverviews(data){
 if(data._projectOverviewsVersion>=1||!data._portfolioPresentationVersion)return;
 const labels=new Map(data.categories.flatMap(c=>c.skills).map(s=>[s.id,s.label]));
 const roles={
 'solar-trash':'Project management, gameplay programming, environment design and game design',
 'desktop-detective':'Game design, prototyping, gameplay programming and interface design',
 'daisychain':'Directing, producing, editing and story. Assistance with casting, location scouting, scheduling, post-production coordination and budgeting',
 'perhaps':'Producing, camera operation and location sound. Assistance with casting, location scouting, scheduling, post-production coordination and budgeting',
 'oh-what-a-night':'Camera operation',
 'framechanger':'Python desktop application, interface design, API integration and data persistence',
 'procedural-2d-tree-generator':'Python desktop tool, procedural generation, interface implementation and data persistence'
 };
 const summaries={
 'solar-trash':'A solarpunk game about restoring a polluted environment. My contribution covered project management, gameplay programming, environment design and game design within the team.',
 'desktop-detective':'A solo investigation-game prototype built around a desktop interface. The player works with scattered evidence and connects information to investigate a case.',
 'daisychain':'A short film released in 2021. I worked on directing, producing, editing and the story, and helped with the planning and coordination needed to take the film through production.',
 'perhaps':'A short film released in 2021. My work covered producing, camera operation and location sound, alongside practical help with casting, locations, scheduling, budgeting and post-production coordination.',
 'oh-what-a-night':'A film project from 2022 on which I worked as a camera operator.',
 'framechanger':'A desktop wallpaper application for finding and displaying artwork from favourite films and TV shows. Built with Python and PyQt5, it connects to TMDB and stores favourites and settings locally.',
 'procedural-2d-tree-generator':'A Python desktop tool that generates fractal trees from adjustable parameters. It supports exporting images and saving or loading settings so a generated result can be revisited.'
 };
 for(const c of data.categories)for(const skill of c.skills)delete skill.displayGroup;
 for(const p of data.projects){
  p.skillIds=[...new Set([...(p.skillIds||[]),...p.sections.flatMap(s=>s.skills)])];
  p.pageEnabled=true;p.publicDestination='page';p.skillLinkMode='auto';
  if(p.id==='portfolio-studio-desk'){p.writeupPublished=true;continue;}
  p.writeupPublished=false;
  if(!p.tagline)p.tagline=p.description;
  if(!p.summary)p.summary=summaries[p.id]||(p.groupId==='illustration'?p.title+' is a digital illustration from my visual art work. The piece is shown above, with a link to its original post below.':p.groupId==='renders'?p.title+' is a 3D rendering project exploring composition, lighting and colour. The image is shown above, with its original post linked below.':p.groupId==='animation'?p.title+' is a 2D animation study exploring movement and timing. Use the link below to watch the animation.':p.description);
  if(!p.playUrl)p.playUrl=p.externalUrl;
  if(p.id!=='nightshift')p.playLabel=p.groupId==='games'?'Play on itch.io':p.groupId==='films'?'Watch the film':p.groupId==='animation'?'Watch the animation':p.groupId==='creative-coding'?'View the project':'View the original post';
  const facts=p.facts.filter(f=>f.value?.trim());
  if(!facts.some(f=>/my work/i.test(f.label)))facts.unshift({label:'My work',value:roles[p.id]||p.skillIds.map(id=>labels.get(id)).filter(Boolean).join(', ')});
  if(!facts.some(f=>/format/i.test(f.label)))facts.push({label:'Format',value:data.groups.find(g=>g.id===p.groupId)?.label||'Creative project'});
  facts.push({overviewOnly:true,label:'About this page',value:'Project overview. A fuller process write-up and post-mortem are being prepared.'});p.facts=facts;
  p.introBlocks=['projectTitle','projectImage','projectTagline','projectSummary','playLink','facts'].map(type=>({id:p.id+'-'+type,type}));
  p.endBlocks=p.endBlocks.filter(b=>b.type!=='facts');
 }
 data.copy.skillsIntro='Each skill has its own row. Follow a dot to the project where I used it, or to the relevant write-up section when available. Hover or focus a dot for the project name. Dots count examples, not proficiency.';
 data.copy.readCaseStudy='View project';
 data._projectOverviewsVersion=1;
}

const portfolioExplanation={"id": "portfolio-studio-desk", "slug": "portfolio-studio-desk", "title": "Portfolio & Studio Desk", "groupId": "creative-coding", "description": "The portfolio you’re browsing, plus a custom editor for writing, organising and publishing it.", "tagline": "This website, and the custom editor that keeps it growing.", "summary": "This is the website you are browsing, together with Studio Desk, the custom editor built to maintain it. Think of Studio Desk as a personal Squarespace of sorts, made around this portfolio’s pages, projects and skill links. The public site brings my games, films, artwork and software into one home, and connects the roles I use to describe myself to work that demonstrates them.", "banner": "assets/case-study/home.jpg", "bannerAlt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "featured": false, "status": "published", "pageEnabled": true, "externalUrl": "", "playUrl": "", "playLabel": "Explore the portfolio", "gameplay": {"type": "video", "src": "", "alt": "", "caption": "", "placeholder": ""}, "sections": [{"id": "what-it-is", "heading": "What it is", "label": "What it is", "sidebar": true, "skills": ["product-definition", "information-architecture"], "blocks": [{"id": "portfolio-what-it-is", "type": "text", "text": "This project has two connected halves. One is the portfolio you are using right now. The other is Studio Desk, the browser-based editor that lets me keep changing it. We built both together, so presenting the work and maintaining the website could be part of the same process.\n\nA personal Squarespace of sorts is a useful way to describe Studio Desk. I can open it, edit a project, upload images, arrange sections, preview the result and publish. The comparison describes the experience I wanted. Studio Desk is our own custom editor, built around this website’s structure and needs.\n\nThe portfolio gives all my work a home. A game, a short film, an illustration and a Python tool can each have their own page, while the Skills page shows connections between them. That matters because the work does not fit neatly inside one job title. Producing a film and coordinating a game involve different outputs, but some of the planning, communication and decision-making carry across.\n\nThe site is still under construction. Every project currently has an introductory page, and this portfolio is the first project with a published, detailed write-up. The plan is to develop the other pages into project post-mortems: what I set out to do, my contribution, the choices I made, what worked, what did not and what I learned. Their introductions can be useful now while those deeper stories take shape."}]}, {"id": "starting-point", "heading": "How it started", "label": "How it started", "sidebar": true, "skills": ["concept-development", "creative-direction"], "blocks": [{"id": "portfolio-starting-point-text", "type": "text", "text": "I find it difficult to pitch myself. I have worked on games, films, illustrations, animations and software, but I struggle to fit all of that into one title. Sometimes calling myself a designer feels too broad. Calling myself a developer leaves out the production and visual work. Listing everything can sound like I am trying to be everything at once.\n\nImposter syndrome is part of that. It is easier for me to talk about something I made than to stand in front of someone and announce what I am good at. I wanted a portfolio that could help with that conversation, but I also wanted a way to understand the work for myself.\n\nThe starting point was a collection of links on my bio site. That gave people somewhere to find things, but it did not explain how the projects connected, what I contributed or why I made particular decisions. This website became an attempt to answer those questions."}]}, {"id": "brief", "heading": "What the website needed to do", "label": "What the website needed to do", "sidebar": true, "skills": ["product-definition", "scope-delivery"], "blocks": [{"id": "portfolio-brief-text", "type": "text", "text": "The starting brief was simple to say and surprisingly demanding to deliver: make my work understandable, make the website feel like mine and let me keep updating it myself.\n\nFor a visitor, that meant clear routes into the projects, descriptions of my contributions and a layout that works on a phone as well as a desktop. A recruiter should be able to scan the work quickly. Someone interested in how a project was made should be able to stay and read the detail. Neither should have to know my history before the page makes sense.\n\nFor me, it meant control over the content after the website was built. I wanted to change a heading, add an image in the middle of a write-up, rearrange sections, update skills and change colours without reopening the source code every time. Those requirements grew into Studio Desk.\n\nThere were practical constraints too. The GitHub version needed to work without a server I had to maintain or another paid hosting subscription. I also wanted to decide when the portfolio was public, while still being able to edit it. Suddenly this was more than choosing a homepage layout. It was a small publishing system, with a public experience and an editing experience that both needed to work."}]}, {"id": "evidence", "heading": "Projects as evidence", "label": "Projects as evidence", "sidebar": true, "skills": ["information-architecture", "ui-ux"], "blocks": [{"id": "portfolio-evidence-text", "type": "text", "text": "The Skills page began as a way to make a vague question more concrete: what have I done that supports the way I describe myself? A long list of titles was not helping me answer it. Looking at the work behind each title was.\n\nEvery skill gets its own row. Each dot represents one project where I used that skill. Hovering over a dot or reaching it with the keyboard reveals the project’s name, and following it takes you to that project. The dots count examples. They are not a self-awarded proficiency score, and a larger count does not establish expertise.\n\nThere are two levels of detail. A project overview can support a skill before its full story is ready. Once a published section explains that work, the dot can go directly to the relevant heading. A visitor interested in interaction design, for example, can open a section explaining the website’s interactions instead of reading the entire portfolio case study to find it.\n\nI tried grouping multiple skills into shared rows to make the page shorter. That weakened the idea because one dot could then stand for several different things. Individual rows preserve the connection between a particular skill and its evidence. Broader categories still help people scan without combining the skills themselves.\n\nThis structure also helps me see patterns across my work. It gives me something specific to refer to when introducing myself, and it lets a visitor choose the route that interests them: start with a project and explore its process, or start with a skill and see where I used it."}, {"id": "portfolio-skills-screenshot", "type": "image", "src": "assets/case-study/skills-iteration.jpg", "alt": "An earlier Skills page showing grouped skill labels with project evidence dots.", "caption": "An earlier live iteration of Skills. The project dots established the browsing model; the categories were later consolidated to make it easier to scan."}, {"id": "portfolio-skill-route-screen", "type": "image", "src": "assets/case-study/role-evidence.jpg", "alt": "Individual development skill rows, with the Unreal Engine row highlighted and a separate project dot for each example.", "caption": "Following the homepage role reaches this row. Its separate dots lead to NightShift, Solar Trash and Desktop Detective."}]}, {"id": "identity", "heading": "An introduction without one fixed title", "label": "An introduction without one fixed title", "sidebar": true, "skills": ["interaction-design", "content-design"], "blocks": [{"id": "portfolio-identity-text", "type": "text", "text": "Choosing one fixed title for the homepage felt limiting. Game design, film production, illustration and software all belong here, and I wanted the introduction to acknowledge that range without presenting an unconnected wall of labels.\n\nThe rotating roles come from the skills recorded in Studio Desk. A role appears only when it has linked project evidence. For example, Unreal Engine Developer connects to the Unreal Engine skill, while Film Director connects to directing. Each title is a clickable link to its skill row, and the dots in that row lead onward to the projects behind it. The intended journey is role, then skill, then evidence.\n\nThe selection is weighted by the number of linked projects. A skill represented in more projects is more likely to appear. This is a way to give the introduction some relationship to the work available to explore, rather than treating every possible title as equally representative. It is still a browsing device, not a ranking of professional seniority.\n\nA pause control lets someone stop the movement and read. Previous and next controls let them cycle through the roles themselves, using the same weighted selection rules. Clicking the title remains the main action: it should open something tangible, rather than be decoration.\n\nThe wording has been revised through feedback too. Labels that were vague or overstated what the linked work showed were replaced with more descriptive names. Studio Desk lets me edit a role or leave it blank, so a skill can remain on the site without becoming part of my introduction."}, {"id": "portfolio-role-screen", "type": "image", "src": "assets/case-study/role-photo.jpg", "alt": "Homepage showing the clickable Unreal Engine Developer role beside the portrait card and pause, previous and next controls.", "caption": "A role is an entry point. Selecting Unreal Engine Developer opens its individual skill row."}]}, {"id": "visual-language", "heading": "Choosing the visual language", "label": "Choosing the visual language", "sidebar": true, "skills": ["art-direction", "ui-ux"], "blocks": [{"id": "portfolio-visual-language-text", "type": "text", "text": "The visual direction uses a grid, strong type, restrained borders and small accent details. I wanted the projects to feel connected even though they come from different media. The interface needed enough personality to feel like mine without competing with the work.\n\nLight and dark themes share a palette system. Studio Desk offers preset combinations and individual colour controls, along with the ability to remove presets I do not want. The palette became part of the editing experience rather than a permanent choice buried in a stylesheet.\n\nWe revised prominence through feedback. A stronger highlight on Selected projects felt too loud, so I asked to revert it. The accent highlight moved to a smaller View all work link at the end of the section. Its bounding box and arrow were removed. That gave the invitation to continue browsing more emphasis without making the whole section shout."}]}, {"id": "portrait", "heading": "Making the portrait feel responsive", "label": "Making the portrait feel responsive", "sidebar": true, "skills": ["interaction-design", "usability-iteration"], "blocks": [{"id": "portfolio-portrait-text", "type": "text", "text": "The portrait started as a box containing my initials. I liked how that fitted the site, but I also wanted the option of using an image. A two-sided card let both ideas stay: the uploaded image on one side, the initials and location on the other.\n\nThe image is shown first. A click or tap turns the card once. Holding and dragging gives direct control over its rotation, and releasing it lets it coast according to the movement. The axis runs vertically, so it turns left to right. A new drag can interrupt the spin and redirect it, which makes the interaction feel closer to handling an object.\n\nThe details came through repeated use and feedback. Earlier versions spun when the pointer passed over the card, sometimes much too quickly. That made an accidental movement compete with the introduction. The interaction moved to a deliberate held-pointer gesture, with hover alone doing nothing. Dragging into the card while already holding the pointer can also begin a spin.\n\nThe screenshots show the two settled sides. They cannot convey the motion, but they show why the flip exists: an image and a compact personal mark can occupy the same space without turning the homepage into a carousel. Keyboard activation also flips once, and reduced-motion preferences simplify the movement. The card is optional to use. Visitors can continue to the work without touching it."}, {"id": "portfolio-card-initials-screen", "type": "image", "src": "assets/case-study/card-initials.jpg", "alt": "The homepage portrait card after a click, showing AS initials instead of the uploaded windmill image.", "caption": "The same card after a flip. The uploaded image and initials remain two sides of one object."}]}, {"id": "navigation", "heading": "Fixing the Work menu", "label": "Fixing the Work menu", "sidebar": true, "skills": ["information-architecture", "interaction-design", "usability-iteration"], "blocks": [{"id": "portfolio-navigation-text", "type": "text", "text": "The Work menu exposed a problem that was easy to miss when looking at a still image. Expanding Games pushed the categories below it down. When the pointer moved towards Film, Games collapsed and those targets moved back up underneath the pointer. A visitor could end up on a different category without intending to.\n\nKeeping every visited category open stopped that movement, but introduced another problem: the menu grew until it needed its own scroll area. That was not the interaction I wanted either.\n\nThe next approach kept the category positions fixed and opened project links in a side panel. Hovering Work shows only the categories. Hovering a category opens its panel, with a short animation when it opens and closes. The panel can change side when it needs room near the viewport edge. Long categories show a limited set of projects and a link to the full category instead of a long scrolling menu.\n\nClick and keyboard controls remain available. Closing panels become non-interactive while they animate away, and interrupted animations cannot close a panel that has already reopened. Those details matter because the menu needs to remain usable when someone moves faster than the animation."}]}, {"id": "case-studies", "heading": "Giving the work a readable structure", "label": "Giving the work a readable structure", "sidebar": true, "skills": ["content-design", "information-architecture"], "blocks": [{"id": "portfolio-case-studies-text", "type": "text", "text": "A project page needs to be useful before I have written its entire history. That led to separating the introduction from the longer write-up underneath it.\n\nEvery project now has a page with its title, an image, a one-line introduction, a summary and details about my contribution. The original viewing or download link stays available, whether that opens a game on itch, a film, an animation or an artwork post. These pages give the work a stable home within the portfolio.\n\nThe lower part is where each project will develop into a post-mortem. Sections can explain a design problem, a production task, a technical decision or a lesson from the process. The sidebar links to those headings, and each section can be associated with the skills it demonstrates. A visitor following a skill dot can then arrive at the relevant part of the story.\n\nStudio Desk keeps that write-up separate from the overview’s publication. I can leave the lower part hidden while I edit it, preview unpublished sections privately and publish the ready sections when I choose. NightShift’s existing writing is preserved in the editor under this arrangement, while visitors currently see its overview. This website’s case study is the first full write-up available to read.\n\nThis makes adding depth a gradual process. A project does not need to disappear while I work out how to explain it, and a half-written section does not need to be shown to visitors because the introduction is ready."}, {"id": "portfolio-writeup-controls", "type": "image", "src": "assets/case-study/writeup-controls.jpg", "alt": "Studio Desk showing NightShift’s write-up publication checkbox left off, its skill-link destination setting and a mobile preview of the overview.", "caption": "A local editor demonstration. NightShift’s introduction is available while its existing write-up stays unpublished. The private preview control can reveal that writing for editing."}]}, {"id": "studio-desk", "heading": "Why Studio Desk became part of the project", "label": "Why Studio Desk became part of the project", "sidebar": true, "skills": ["product-definition", "content-design", "systems-design"], "blocks": [{"id": "portfolio-studio-desk-text", "type": "text", "text": "I wanted the site to remain mine to maintain after it was built. If adding a paragraph or moving an image meant returning to a development conversation every time, the editor would not have achieved its purpose.\n\nStudio Desk is the name we gave the custom editing interface. It runs in the browser and works with the content and page structure used by this portfolio. The closest everyday comparison is a personal website builder: choose a page, edit its content, arrange its blocks, check the preview and publish when ready.\n\nThere are controls for the homepage, project groups, individual skills, contact cards, colours, shared wording and media. Each project has an Overview, Sections and Credits & details. The layout editor can insert paragraphs, headings, images, GIFs, videos, galleries, quotes and text beside an image. Blocks and sections can be moved with handles or keyboard-friendly arrow buttons, and custom blocks can move between sections.\n\nThe skill links are part of that editing process. I can select skills for the whole project, link a skill to a particular section or hide a project’s dot. The automatic destination uses a published section when one exists and the project overview otherwise. There are also options to show only section-backed dots, retain an external destination or hide a project from Skills. That means the evidence can become more precise as I write, without rebuilding the Skills page by hand.\n\nThe editor also has limits. It offers control over the content, the supplied layouts and the relationships between pages. Adding a completely new interaction or a new kind of block still involves changing the implementation. The goal was to make ordinary portfolio maintenance independent, while keeping a coherent design and a manageable editing experience."}, {"id": "portfolio-editor-screenshot", "type": "image", "src": "assets/case-study/studio-desk.jpg", "alt": "Studio Desk with page controls on the left, editable homepage content in the centre and the rendered portfolio preview on the right.", "caption": "Studio Desk in a read-only local demonstration: content controls and the rendered page sit side by side. This screenshot does not show a connected GitHub session."}]}, {"id": "preview", "heading": "Getting the preview out of the way", "label": "Getting the preview out of the way", "sidebar": true, "skills": ["usability-iteration", "interaction-design"], "blocks": [{"id": "portfolio-preview-text", "type": "text", "text": "A useful editor needs a good feedback loop. If I change a colour or move a block, I want to see what happened while the decision is still fresh. That became one of the most important parts of Studio Desk.\n\nThe preview initially swung between two frustrating extremes. Frequent refreshes felt disruptive, while manual refreshes made even small changes feel disconnected from their result. The current approach waits briefly after an edit, then updates automatically. It remembers the page scroll position and the chosen light or dark theme, so I can keep looking at the same part of the page as I work.\n\nDesktop and mobile preview sizes help me compare how the layout responds. Changing a palette is particularly useful this way: I can see it across the actual page instead of trying to imagine a website from three colour swatches.\n\nTechnically, the preview runs in a sandboxed iframe, a separate document inside the editor. Styles, scripts and media are supplied so it can render without relying on an authenticated request for every asset. The interaction script runs after the document content exists. Messages between the preview and editor keep track of scroll and theme state, while a version check prevents an older render response from replacing a more recent edit. Each of those details supports the same goal: let me stay focused on the thing I am changing."}]}, {"id": "implementation", "heading": "How the implementation is organised", "label": "How the implementation is organised", "sidebar": true, "skills": ["systems-design", "technical-specification"], "blocks": [{"id": "portfolio-implementation-text", "type": "text", "text": "The public site is built with HTML, CSS and JavaScript. HTML gives the pages their structure, CSS handles the visual system and responsive layouts, and JavaScript adds behaviours such as the rotating introduction, project menus, theme switch and portrait interaction. There is no React-style component framework required to display the portfolio.\n\nThe content lives in structured data rather than being scattered through individual page files. A project contains its description, sections, blocks, skills and publication settings. Rendering functions turn that data into HTML. This makes a project reusable in several places: the same record can supply its Work card, featured card, menu entry, skill links and detailed page.\n\nThe page builder uses that same idea at a smaller scale. A text block, image block or gallery has its own content and layout settings. The renderer knows how to display each type. This is what makes moving an image between paragraphs or rearranging the introduction possible without rewriting the page template.\n\nThe renderer is shared by preview and export. The editor is not maintaining a separate imitation of the page; it uses the same rendering logic that prepares the published output. Node.js build scripts package the templates, public assets and editor distribution. Versioned asset URLs help updated editor files load together rather than mixing a cached old script with a new interface.\n\nThe implementation also handles the small details that make a static site practical: project links are converted into clean page routes, relevant media files are collected for publication, draft-only pages are excluded and relative paths can accommodate a GitHub project subdirectory. The result is ordinary website files that can be served by GitHub Pages, with the richer editing behaviour living in the browser."}]}, {"id": "publishing", "heading": "Separating editing from publishing", "label": "Separating editing from publishing", "sidebar": true, "skills": ["systems-design", "product-definition"], "blocks": [{"id": "portfolio-publishing-text", "type": "text", "text": "GitHub Pages serves the public portfolio as static files. Studio Desk supplies the editing and publishing workflow that sits in front of those files. It talks to GitHub through its API, the interface that lets software read and update repository content.\n\nThere are two repositories in the workflow. The private repository holds the draft, uploaded files and history. The public Pages repository holds the website that visitors can see. Publishing renders the selected content, gathers the media it needs and updates the public files. Saving a draft is a separate action, so unfinished writing can stay private.\n\nThe publishing screen distinguishes a current live site from one with unpublished changes. It can also take the public portfolio offline while retaining access to Studio Desk. That replaces the public pages with an unavailable screen; previously public files can still exist in caches or repository history.\n\nThere is also an editor-only update. This refreshes Studio Desk itself while preserving the portfolio’s current publication state. That distinction was essential while the tool was being developed: improving the editor should not unexpectedly publish a new paragraph or switch the portfolio online.\n\nThe original setup environment uses a Worker and object storage, but the GitHub edition does not require that server for everyday editing and publishing. Its editor runs in the browser, the content lives in GitHub and Pages serves the output. A short deployment delay was an acceptable trade-off for having a workflow I could use independently."}]}, {"id": "access", "heading": "Access and saved connections", "label": "Access and saved connections", "sidebar": true, "skills": ["technical-specification", "interaction-design"], "blocks": [{"id": "portfolio-access-text", "type": "text", "text": "The editor connects using a GitHub access token with access to the relevant repositories. A secret-looking editor URL is not the security boundary; repository permissions and the token are what control access to the private content and publishing operations.\n\nTyping the token every time was inconvenient, so an optional local unlock password was added. The password encrypts the saved token in that browser using browser cryptography. It is not a separate account service or a replacement for GitHub permissions. An expired token still has to be replaced.\n\nThe choice to remember the connection is optional, which matters on shared or work computers. The editor can also clear the connection. These are usability decisions around an existing credential, not a claim that the project provides a fully audited authentication platform."}]}, {"id": "draft-conflicts", "heading": "Protecting edits when drafts disagree", "label": "Protecting edits when drafts disagree", "sidebar": true, "skills": ["systems-design", "usability-iteration"], "blocks": [{"id": "portfolio-draft-conflicts-text", "type": "text", "text": "One of the less visible features became one of the most valuable: protecting text when two versions of a draft disagree. Imagine leaving Studio Desk open on one computer, making a change elsewhere, then returning to the first tab. That tab is now editing an older version.\n\nThe save process compares three things: the draft the tab started from, the local edits and the latest draft on GitHub. If the changes affect different fields, they can be combined. If both versions changed the same field, the editor asks which version to keep. It also preserves recovery copies instead of silently throwing one away.\n\nThere is another race to handle while a save is in progress. If I keep typing before the response comes back, the newly typed text must not be overwritten by the result of the earlier save. The editor keeps those newer changes pending for the next save. Downloadable backups provide an additional route out of a problem.\n\nIt is easy to describe a content editor as a set of text boxes and a Publish button. This part of the project showed how much care sits behind those controls. The editor needs to protect the work while making the state of that work understandable."}]}, {"id": "feedback", "heading": "What feedback changed", "label": "What feedback changed", "sidebar": true, "skills": ["usability-iteration", "production-planning"], "blocks": [{"id": "portfolio-feedback-text", "type": "text", "text": "A conversation with my WorkBC recruiter led to another round of revisions. The photograph needed to appear first. Hovering across the homepage should not accidentally spin the portrait. There needed to be a clearer route from featured projects to the full collection. Contact information needed its own page as well as a place in the footer.\n\nThe Contact page then changed again. Separating email from social links felt unnecessarily rigid, so the links became one column of matching cards. The cards can show a short invitation on hover or keyboard focus, and those messages can be edited in Studio Desk. The text transition was shortened when it felt sluggish.\n\nThis was informal feedback and repeated use, not a formal usability study. It identified specific problems and helped me change the design, but it does not establish that the site works equally well for every visitor. I have no measured recruitment conversion or time-saving result to attach to it."}]}, {"id": "accessibility", "heading": "Accessibility and the remaining trade-offs", "label": "Accessibility and the remaining trade-offs", "sidebar": true, "skills": ["accessibility-design", "usability-iteration"], "blocks": [{"id": "portfolio-accessibility-text", "type": "text", "text": "The site includes keyboard focus treatments, a skip link, labelled controls, project-name tooltips available on focus, reduced-motion support and responsive layouts. The role animation can be paused. Touch interaction is considered separately from hover, particularly for the portrait and navigation.\n\nThat does not mean the work is finished or that the site has been certified against an accessibility standard. Functional checks cover specific behaviours. They do not replace testing with assistive technology or observing people using the site.\n\nOne unresolved decision is colour contrast. The palette originally adjusted accent text for each background. I preferred the consistency of using the exact same accent in both themes, so that adjustment was removed. Bright accents can be difficult to read on light backgrounds, and white text on a bright accent button can also be weak. A stronger next iteration would preserve the accent for decorative elements and define accessible foreground/background pairings for text and controls.\n\nI also want to revisit page-wide text-selection suppression, test the menus at high zoom and check the full editing and publishing journey with keyboard and screen-reader users. These are specific improvements to work towards, not features I am claiming are already solved."}]}, {"id": "my-contribution", "heading": "My role and the implementation process", "label": "My role and the implementation process", "sidebar": true, "skills": ["creative-direction", "technical-specification"], "blocks": [{"id": "portfolio-my-contribution-text", "type": "text", "text": "I defined the problem, set the constraints and directed the product through repeated rounds of feedback. The evidence-based Skills page, rotating introduction, project-page structure and requirement for an independently usable editor came out of those decisions.\n\nImplementation was AI-assisted. I used that support to develop the code, investigate problems and iterate on the site and editor. My contribution centred on product definition, creative direction, information architecture, interaction decisions, content and testing through use.\n\nWhat I want this project to show is the process behind the experience: noticing what is confusing, being specific about what should change and following the consequences of those choices all the way through the product."}]}, {"id": "reflection", "heading": "What I learned and what comes next", "label": "What I learned and what comes next", "sidebar": true, "skills": ["scope-delivery", "content-design"], "blocks": [{"id": "portfolio-reflection-text", "type": "text", "text": "The project started as a way to show my work and became a way to understand it. Having to connect a skill to a project forced me to be more specific about what I had done. It also made it easier to see where I was relying on a vague label or borrowing credit from a team outcome.\n\nThere is a similar lesson in the interface. A spinning card can look good and still interrupt the visitor. A dropdown can look tidy until the targets move under the pointer. A preview can be technically working and still make editing frustrating. The revisions often came from noticing that difference.\n\nIf I were starting again, I would settle the content structure and the editor/publication boundary earlier. I would also put more deliberate limits on custom interactions until the basic browsing and editing flows were tested. The site has accumulated revisions, and simplifying the implementation is part of keeping it maintainable.\n\nThe next steps are to write more project case studies, improve contrast without losing the visual identity, test accessibility more systematically and keep checking whether the Skills page helps someone find relevant work quickly. I still find it difficult to put one label on myself. The difference is that I now have a clearer way to show what sits behind those labels.\n\nThe next stage is to bring the other projects up to the same level of detail. Their overview pages are already in place. As I finish each post-mortem, I can publish its sections and connect individual skills to the work they describe. The portfolio can become more informative over time without needing another redesign to accommodate that depth."}]}], "credits": [], "facts": [{"label": "My work", "value": "Product direction, experience design, information architecture, writing and iterative testing"}, {"label": "Implementation", "value": "Custom HTML, CSS and JavaScript · browser-based editing · GitHub API · static GitHub Pages publishing"}, {"label": "Project status", "value": "Under construction · project overviews available · portfolio case study published · other post-mortems in progress"}], "introBlocks": [{"id": "portfolio-projectTitle", "type": "projectTitle"}, {"id": "portfolio-overview-screenshot", "type": "image", "src": "assets/case-study/home.jpg", "alt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "caption": "The live homepage, captured during development. The introduction links roles to the work behind them."}, {"id": "portfolio-projectTagline", "type": "projectTagline"}, {"id": "portfolio-projectSummary", "type": "projectSummary"}, {"id": "portfolio-facts", "type": "facts"}], "endBlocks": [{"id": "portfolio-endLinks", "type": "endLinks"}]};
function applyPortfolioExplanation(data){if(data._portfolioExplanationVersion>=1||!data._projectOverviewsVersion)return;const p=data.projects.find(p=>p.id==='portfolio-studio-desk');if(p){p.summary=portfolioExplanation.summary;p.facts=structuredClone(portfolioExplanation.facts);p.sections=structuredClone(portfolioExplanation.sections);for(const section of p.sections)section.published=true;}data._portfolioExplanationVersion=1;}

const skimmableCase={"id": "portfolio-studio-desk", "slug": "portfolio-studio-desk", "title": "Building this portfolio", "groupId": "creative-coding", "description": "The portfolio you’re browsing, plus a custom editor for writing, organising and publishing it.", "tagline": "I built this portfolio, then added a custom editor so I could keep developing it myself.", "summary": "A portfolio built with HTML, CSS and JavaScript, published on GitHub Pages, with a custom browser-based editor for updating it from the same website. The editor uses the GitHub API to save private drafts and publish static pages, without a separate application server to host. Visitors can follow a homepage role to an individual skill, then follow its project dots to examples of my work. I shaped the experience, content structure and interactions through repeated testing and feedback.", "banner": "assets/case-study/home.jpg", "bannerAlt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "featured": false, "status": "published", "pageEnabled": true, "externalUrl": "", "playUrl": "", "playLabel": "Explore the portfolio", "gameplay": {"type": "video", "src": "", "alt": "", "caption": "", "placeholder": ""}, "sections": [{"id": "what-it-is", "heading": "One home for the work, with evidence behind the titles", "label": "Product definition", "sidebar": true, "published": true, "skills": ["product-definition", "concept-development", "creative-direction", "scope-delivery"], "blocks": [{"id": "what-it-is-points", "type": "text", "text": "- **The problem:** I make games, films, illustrations, animations and software. A collection of links showed the results, but gave people little help understanding my contribution or the connections between projects.\n- **The idea:** give each project a home and connect the skills behind it. Visitors can browse by the work that interests them or start with a capability they need.\n- **The personal reason:** I find pitching myself difficult. Imposter syndrome makes choosing titles uncomfortable. Connecting each title to something I have made gives me a more concrete way to describe my work.\n- **Current state:** every project has an overview. This portfolio has the first full published post-mortem. The other write-ups will explain contributions, decisions, challenges and lessons as I finish them."}, {"id": "what-it-is-screenshot", "type": "image", "src": "assets/case-study/home.jpg", "alt": "One home for the work, with evidence behind the titles illustrated in the portfolio or local editor preview.", "caption": "Portfolio interface."}]}, {"id": "identity", "heading": "An introduction you can follow into the work", "label": "Content design", "sidebar": true, "published": true, "skills": ["content-design", "information-architecture"], "blocks": [{"id": "identity-points", "type": "text", "text": "- **Role → skill → project:** click a rotating title to reach its individual skill row. Each dot in that row opens a project demonstrating that skill, or the relevant published section of its write-up.\n- **Titles come from evidence:** the editor associates role names with skills. Roles without linked project evidence are excluded from the introduction.\n- **Weighted selection:** a skill with more linked projects receives more weight in the random selection. This represents the available examples, not a measurement of seniority or proficiency.\n- **Visitor control:** pause the rotation to read at your own pace, or use the previous and next arrows. Role wording and timing remain editable."}, {"id": "identity-screenshot", "type": "image", "src": "assets/case-study/role-photo.jpg", "alt": "An introduction you can follow into the work illustrated in the portfolio or local editor preview.", "caption": "Portfolio interface."}]}, {"id": "evidence", "heading": "Individual skills, connected to specific examples", "label": "Information architecture", "sidebar": true, "published": true, "skills": ["information-architecture", "ui-ux"], "blocks": [{"id": "evidence-points", "type": "text", "text": "- **One row per skill:** broad categories help navigation, while each skill keeps its own identity and project links.\n- **One dot per project:** hover or keyboard focus reveals the project name. The dots represent examples of work rather than self-assessed ratings.\n- **Increasing precision:** an overview supports a project-level link now. Publishing a section associated with that skill moves the automatic link directly to that section.\n- **A useful correction:** combining skills into shared rows shortened the page but weakened the connection between each capability and its evidence. Returning to individual rows restored the purpose of the index."}, {"id": "evidence-screenshot", "type": "image", "src": "assets/case-study/role-evidence.jpg", "alt": "Individual skills, connected to specific examples illustrated in the portfolio or local editor preview.", "caption": "Portfolio interface."}]}, {"id": "portrait", "heading": "Small interactions that feel deliberate and responsive", "label": "Interaction design", "sidebar": true, "published": true, "skills": ["interaction-design", "art-direction", "usability-iteration"], "blocks": [{"id": "portrait-points", "type": "text", "text": "- **The portrait card:** the image appears first. Click or tap to reveal the initials. Hold and drag horizontally to rotate it, release to let it coast, and drag again to interrupt or reverse its movement.\n- **Discoverable without distraction:** a small instruction below the card explains the gesture. Hovering alone does not spin it.\n- **The Work menu:** categories open adjacent panels so expanding a category does not push the next category away from the pointer. Matching transitions soften opening and closing.\n- **Consistent feedback:** hover, focus and pressed states acknowledge interaction. The goal is a satisfying interface that keeps the work easy to reach, rather than motion that competes with it.\n- **Feedback changed the design:** accidental hover spins, excessive rotation and shifting menu items were revised after use exposed how distracting they could be."}, {"id": "portrait-screenshot", "type": "image", "src": "assets/case-study/card-initials.jpg", "alt": "Small interactions that feel deliberate and responsive illustrated in the portfolio or local editor preview.", "caption": "Portfolio interface."}, {"id": "portrait-other-side", "type": "image", "src": "assets/case-study/role-photo.jpg", "alt": "The image side of the same portrait card.", "caption": "The image side before a click reveals the initials."}]}, {"id": "accessibility", "heading": "Give visitors control over motion and navigation", "label": "Accessibility considerations", "sidebar": true, "published": true, "skills": ["accessibility-design", "usability-iteration"], "blocks": [{"id": "accessibility-points", "type": "text", "text": "- **Motion controls:** pause the rotating titles, cycle them manually, and use a single click or keyboard activation to flip the card. Reduced-motion preferences simplify animated behaviour.\n- **Keyboard and reading support:** skip navigation, visible focus states, labelled controls, image descriptions and project-name tooltips support ways of browsing beyond a mouse.\n- **Long-page navigation:** a section index, floating back-to-top control and a theme-aware bottom scroll hint help visitors move through a write-up. The hint disappears at the bottom.\n- **Responsive layouts:** navigation and project content adapt to smaller screens. The editor includes a mobile preview for checking changes.\n- **An ongoing responsibility:** these are implemented considerations, not a claim of comprehensive accessibility compliance. Contrast, assistive-technology use and interaction choices need continued evaluation."}, {"id": "accessibility-screenshot", "type": "image", "src": "assets/case-study/writeup-controls.jpg", "alt": "Give visitors control over motion and navigation illustrated in the portfolio or local editor preview.", "caption": "Local editor demonstration, without a connected GitHub session."}]}, {"id": "studio-desk", "heading": "A personal site builder, tailored to this portfolio", "label": "Systems Design", "sidebar": true, "published": true, "skills": ["systems-design", "production-planning", "technical-specification"], "blocks": [{"id": "studio-desk-points", "type": "text", "text": "- **Why add an editor:** maintaining the portfolio should not require a new coding session for each paragraph, image or project. I wanted control over ordinary updates after the website was built.\n- **Introducing Studio Desk:** this is the name we gave the custom editor. Think of it as a personal Squarespace of sorts, built around this portfolio’s pages and skill relationships.\n- **Content and layout:** edit copy, upload reusable media, add quotes and galleries, and move or resize blocks. Projects, categories, contact links, colours and homepage roles have dedicated controls.\n- **Live preview:** changes update the rendered page alongside the controls. Desktop/mobile previews and light/dark switching help check the result before publication.\n- **Gradual publication:** keep a project overview online while writing its lower sections privately. Mark sections ready, link their skills, then enable the write-up when it is ready to publish.\n- **Clear limits:** new interactions or new block types still require development. The editor makes content maintenance independent within the supplied design system."}, {"id": "studio-desk-screenshot", "type": "image", "src": "assets/case-study/studio-desk.jpg", "alt": "A personal site builder, tailored to this portfolio illustrated in the portfolio or local editor preview.", "caption": "Local editor demonstration, without a connected GitHub session."}]}, {"id": "implementation", "heading": "Static hosting, browser editing and controlled publishing", "label": "Technical specification", "sidebar": true, "published": true, "skills": ["technical-specification", "scope-delivery"], "blocks": [{"id": "implementation-points", "type": "text", "text": "- **Public website:** HTML, CSS and JavaScript are exported as static files for GitHub Pages. Visitors do not need an account to browse the published portfolio.\n- **Editor on the same host:** the browser calls the GitHub API to read and save content and publish files. There is no separate application server for me to maintain. GitHub provides the storage and publishing infrastructure.\n- **Shared rendering:** preview and export use the same rendering logic, reducing differences between the editor’s view and the published page.\n- **Publication boundaries:** private drafts are separate from the public output. Unpublished sections and their referenced media are excluded from the exported project pages.\n- **Recovery and conflicts:** saved versions and backups support recovery. When drafts diverge, the editor protects conflicting changes instead of silently overwriting them.\n- **My contribution:** product direction, experience design, information architecture, writing and iterative testing. Implementation was AI-assisted, including development, debugging and revisions to the site and editor."}, {"id": "implementation-screenshot", "type": "image", "src": "assets/case-study/writeup-controls.jpg", "alt": "Static hosting, browser editing and controlled publishing illustrated in the portfolio or local editor preview.", "caption": "Local editor demonstration, without a connected GitHub session."}]}], "credits": [], "facts": [{"label": "My work", "value": "Product direction, experience design, information architecture, writing and iterative testing"}, {"label": "Implementation", "value": "Custom HTML, CSS and JavaScript · browser-based editing · GitHub API · static GitHub Pages publishing"}, {"label": "Project status", "value": "Under construction · project overviews available · portfolio case study published · other post-mortems in progress"}], "introBlocks": [{"id": "portfolio-projectTitle", "type": "projectTitle"}, {"id": "portfolio-overview-screenshot", "type": "image", "src": "assets/case-study/home.jpg", "alt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "caption": "The live homepage, captured during development. The introduction links roles to the work behind them."}, {"id": "portfolio-projectTagline", "type": "projectTagline"}, {"id": "portfolio-projectSummary", "type": "projectSummary"}, {"id": "portfolio-facts", "type": "facts"}], "endBlocks": [{"id": "portfolio-endLinks", "type": "endLinks"}]};
function applySkimmableCase(data){if(data._skimmableCaseVersion||!data._portfolioExplanationVersion)return;const p=data.projects.find(p=>p.id==='portfolio-studio-desk');if(p){for(const k of ['title','tagline','summary','sections'])p[k]=structuredClone(skimmableCase[k]);p.skillIds=[...new Set(p.sections.flatMap(s=>s.skills))];}data._skimmableCaseVersion=1;}

const caseVisuals={"what-it-is": [{"type": "gallery", "id": "theme-comparison", "items": [{"type": "image", "id": "case-home-light", "src": "assets/case-study/case-home-light.jpg", "alt": "Portfolio homepage in light mode.", "caption": "Light theme: the same content and accent."}, {"type": "image", "id": "case-home-dark", "src": "assets/case-study/case-home-dark.jpg", "alt": "Portfolio homepage in dark mode.", "caption": "Dark theme: the layout and navigation stay consistent."}]}], "identity": [{"type": "image", "id": "case-home-light", "src": "assets/case-study/case-home-light.jpg", "alt": "Homepage role with pause and previous and next controls.", "caption": "Each title is a link to its corresponding skill. The controls let visitors pause or choose another role."}], "evidence": [{"type": "image", "id": "case-skills-links", "src": "assets/case-study/case-skills-links.jpg", "alt": "Individual design skills and clickable project dots, with Interaction design highlighted.", "caption": "A role lands on a highlighted skill. Each dot then opens a project overview or a published section."}], "portrait": [{"type": "image", "id": "card-initials", "src": "assets/case-study/card-initials.jpg", "alt": "The initials side of the homepage card.", "caption": "The reverse face keeps the same frame, spacing and accent corners."}, {"type": "image", "id": "try-card", "src": "assets/bio/isometric-windmill.webp", "alt": "Isometric windmill artwork on the interactive demonstration card.", "interactiveFlip": true, "initials": "AS", "interactionLabel": "Flip or drag to spin the demonstration card", "caption": "Try it: click or tap to flip; drag or swipe to spin. This uses the homepage’s interaction code, including interruption and reduced-motion support."}], "accessibility": [{"type": "image", "id": "case-home-dark", "src": "assets/case-study/case-home-dark.jpg", "alt": "Homepage showing pause, previous and next role controls and theme switch.", "caption": "Visible motion controls let visitors stop the rotation and explore at their own pace."}], "studio-desk": [{"type": "gallery", "id": "editor-theme-comparison", "items": [{"type": "image", "id": "case-editor-light", "src": "assets/case-study/case-editor-light.jpg", "alt": "Editor palettes beside the light website preview.", "caption": "The custom editor with a live light-theme preview."}, {"type": "image", "id": "case-editor-dark", "src": "assets/case-study/case-editor-dark.jpg", "alt": "The same editor with dark website preview.", "caption": "Switching the preview to dark mode keeps editing in place."}]}, {"type": "image", "id": "studio-desk", "src": "assets/case-study/studio-desk.jpg", "alt": "Custom editor with content controls and page preview.", "caption": "Content and layout editing stay beside the page being edited."}], "implementation": [{"type": "image", "id": "case-editor-sections", "src": "assets/case-study/case-editor-sections.jpg", "alt": "Editor controls for publishing the write-up and selecting skill-dot destinations beside the public overview.", "caption": "A local demonstration of publication boundaries: the overview is visible while the write-up remains unpublished."}]};
function applyCaseVisuals(data){if(data._caseVisualsVersion)return;const p=data.projects.find(p=>p.id==='portfolio-studio-desk');if(p){for(const section of p.sections){const additions=caseVisuals[section.id];if(!additions)continue;section.blocks=section.blocks.filter(b=>!((b.type==='image'||b.type==='gallery')&&(b.id===section.id+'-screenshot'||['portrait-photo','portrait-front','portrait-image','portrait-card','portrait-other-side'].includes(b.id))));for(const b of additions)if(!section.blocks.some(x=>x.id===b.id))section.blocks.push(structuredClone(b));}}data._caseVisualsVersion=1;}

const humanCase={"id": "portfolio-studio-desk", "slug": "portfolio-studio-desk", "title": "A project page for the website you’re browsing", "groupId": "creative-coding", "description": "The website you’re browsing, and the custom editor I use to manage it.", "tagline": "A home for my work, with a custom editor to help me look after it.", "summary": "I wanted one place for my games, films, artwork and other projects, with a clearer way to explain what I contributed to each of them. Here, you can follow a role on the homepage to a skill, then choose a project where I used it. Along the way, I wanted the website to feel personal and satisfying to use, while giving visitors control over its motion and navigation. The portfolio runs on GitHub Pages, using HTML, CSS and JavaScript. I also added a custom browser-based editor, which I named Studio Desk, so I can change the content, arrange pages and publish updates from the same website. It uses the GitHub API to save private drafts and publish static files, with no separate application server for me to host.", "banner": "assets/case-study/home.jpg", "bannerAlt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "featured": false, "status": "published", "pageEnabled": true, "externalUrl": "", "playUrl": "", "playLabel": "Explore the portfolio", "gameplay": {"type": "video", "src": "", "alt": "", "caption": "", "placeholder": ""}, "sections": [{"id": "what-it-is", "heading": "Product definition", "label": "Product definition", "sidebar": true, "published": true, "skills": ["product-definition", "concept-development", "creative-direction", "scope-delivery"], "blocks": [{"id": "what-it-is-paragraph-0", "type": "text", "text": "I make games, films, illustrations, animations and software, and I wanted them to feel like parts of the same practice. A list of links could show the finished pieces, but it left out **what I contributed and how the work connects**."}, {"id": "what-it-is-paragraph-1", "type": "text", "text": "I also find it difficult to pitch myself. Imposter syndrome makes choosing a title uncomfortable, especially when my work crosses several disciplines. Connecting a title to something I have made gives me **a concrete example to point to**, rather than expecting someone to take the title at face value."}, {"id": "what-it-is-paragraph-2", "type": "text", "text": "The idea is for each project to have its own home here. **Every project now has an overview**, while the longer case studies are still in progress. This page is the first of those, and the others will explain the decisions, contributions and lessons behind the work as I finish writing them."}, {"type": "gallery", "id": "theme-comparison", "items": [{"type": "image", "id": "case-home-light", "src": "assets/case-study/case-home-light.jpg", "alt": "Portfolio homepage in light mode.", "caption": "Light theme: the same content and accent."}, {"type": "image", "id": "case-home-dark", "src": "assets/case-study/case-home-dark.jpg", "alt": "Portfolio homepage in dark mode.", "caption": "Dark theme: the layout and navigation stay consistent."}]}], "subheading": "One home for the work, with evidence behind the titles"}, {"id": "identity", "heading": "Content design", "label": "Content design", "sidebar": true, "published": true, "skills": ["content-design", "information-architecture"], "blocks": [{"id": "identity-paragraph-0", "type": "text", "text": "I can click on any of the **rotating roles on the homepage** to go straight to the skill it refers to. From that skill’s row, I can choose a project dot to see where I used it. If that project has a published section about the skill, the dot takes me directly there. Otherwise, it opens the project overview."}, {"id": "role-to-skill", "type": "gallery", "items": [{"id": "detail-role", "type": "image", "src": "assets/case-study/detail-role.jpg", "alt": "Unreal Engine Developer role on the homepage.", "caption": "1. Click the Unreal Engine Developer role."}, {"id": "detail-skill", "type": "image", "src": "assets/case-study/detail-skill.jpg", "alt": "Highlighted Unreal Engine skill and its three project dots.", "caption": "2. Arrive at Unreal Engine, then choose a project dot."}]}, {"id": "identity-paragraph-1", "type": "text", "text": "The titles come from the roles I associate with skills in the editor. A role only appears when it has **published project evidence behind it**, so the introduction stays connected to the work instead of becoming a separate list of claims."}, {"id": "identity-paragraph-2", "type": "text", "text": "I gave skills with more linked projects **more weight in the random selection**. That lets the introduction reflect how much work I have documented in an area. It does not score my ability or suggest that a skill with fewer examples matters less."}, {"id": "identity-paragraph-3", "type": "text", "text": "Visitors can **pause the rotation or use the arrows** to explore at their own pace. I can also edit the titles and timing as the work develops."}], "subheading": "An introduction you can follow into the work"}, {"id": "evidence", "heading": "Information architecture", "label": "Information architecture", "sidebar": true, "published": true, "skills": ["information-architecture", "ui-ux"], "blocks": [{"id": "evidence-paragraph-0", "type": "text", "text": "I wanted the skills page to answer a practical question: **where have I used this?** Each skill has its own row, grouped into broader areas so the page is easier to browse without blending distinct skills together."}, {"id": "evidence-paragraph-1", "type": "text", "text": "The dots are **links to projects, not proficiency ratings**. Hovering over a dot or focusing it with a keyboard reveals the project name, so visitors know where they are going before they open it."}, {"id": "evidence-paragraph-2", "type": "text", "text": "I can connect a skill to an individual section of a case study. That means someone interested in a particular part of my work can reach the relevant explanation without having to read the whole page first."}, {"id": "evidence-paragraph-3", "type": "text", "text": "The editor lets me **add or remove project dots and change their destinations**. A dot can point to an overview, a published section or an external project page while I am still preparing the material here."}, {"type": "image", "id": "case-skills-links", "src": "assets/case-study/case-skills-links.jpg", "alt": "Individual design skills and clickable project dots, with Interaction design highlighted.", "caption": "A role lands on a highlighted skill. Each dot then opens a project overview or a published section."}], "subheading": "Individual skills, connected to specific examples"}, {"id": "portrait", "heading": "Interaction design", "label": "Interaction design", "sidebar": true, "published": true, "skills": ["interaction-design", "art-direction", "usability-iteration"], "blocks": [{"id": "portrait-paragraph-0", "type": "text", "text": "I wanted exploring the website to feel **responsive and satisfying**, including the small things people might never consciously notice."}, {"id": "portrait-paragraph-1", "type": "text", "text": "The Work menu opens its projects in **a panel beside the categories**. Expanding a category used to push the categories below it around, which meant the next item could move away from the pointer. The side panel keeps those targets in place, with up to six projects and a link to the full category."}, {"id": "portrait-paragraph-2", "type": "text", "text": "I used **consistent hover, focus and pressed feedback** across links and controls. The arrows, side panels and the small rotating square beside my name give an interaction a visible response without needing a large animation."}, {"id": "portrait-paragraph-3", "type": "text", "text": "The portrait card is a small playful detail. **Clicking or tapping flips it once**, while dragging or swiping gives it momentum based on the gesture. I can interrupt a spin and turn it back the other way instead of having to wait for an animation to finish."}, {"id": "portrait-paragraph-4", "type": "text", "text": "I wanted people to discover it without accidental movement competing with the introduction. The card **stays still on hover**, with a hint that appears on hover or keyboard focus. On touch screens, the hint appears briefly when the card comes into view and disappears when it is used."}, {"id": "card-faces", "type": "gallery", "items": [{"id": "detail-card-image", "type": "image", "src": "assets/case-study/detail-card-image.jpg", "alt": "Image face of the homepage card.", "caption": "The image appears first."}, {"id": "detail-card-initials", "type": "image", "src": "assets/case-study/detail-card-initials.jpg", "alt": "Initials face of the homepage card.", "caption": "Clicking or tapping reveals the initials."}]}, {"type": "image", "id": "try-card", "src": "assets/bio/isometric-windmill.webp", "alt": "Isometric windmill artwork on the interactive demonstration card.", "interactiveFlip": true, "initials": "AS", "interactionLabel": "Flip or drag to spin the demonstration card", "caption": "Try it: click or tap to flip; drag or swipe to spin. This uses the homepage’s interaction code, including interruption and reduced-motion support."}], "subheading": "Small interactions that feel deliberate and responsive"}, {"id": "accessibility", "heading": "Accessibility considerations", "label": "Accessibility considerations", "sidebar": true, "published": true, "skills": ["accessibility-design", "usability-iteration"], "blocks": [{"id": "accessibility-paragraph-0", "type": "text", "text": "I wanted visitors to have **control over movement**. The roles can be paused or stepped through manually, the card does not spin on hover, and reduced-motion preferences simplify the animated interactions."}, {"id": "detail-motion-controls", "type": "image", "src": "assets/case-study/detail-motion-controls.jpg", "alt": "Paused role rotation, with previous and next buttons.", "caption": "Pause or resume the roles, or step through them using the arrows."}, {"id": "accessibility-paragraph-1", "type": "text", "text": "I added **keyboard focus indicators, descriptive control labels and a skip link** so the interface can be explored without relying on a mouse. Project dots also reveal their names on focus, rather than keeping that information behind hover alone."}, {"id": "accessibility-paragraph-2", "type": "text", "text": "The case-study sidebar links to individual sections. A **floating back-to-top button** and a subtle fade near the bottom of the viewport help with longer pages, and the fade disappears at the bottom of the page."}, {"id": "accessibility-paragraph-3", "type": "text", "text": "The layout adapts to **desktop and mobile screens**. Navigation, skill rows and project content rearrange to suit the available space, and the editor includes a mobile preview so I can check changes while working."}, {"id": "accessibility-paragraph-4", "type": "text", "text": "These choices are part of an ongoing process. I still need to keep checking contrast, assistive-technology use and the clarity of interactions as I add content, rather than treating accessibility as something finished."}], "subheading": "Give visitors control over motion and navigation"}, {"id": "studio-desk", "heading": "Systems Design", "label": "Systems Design", "sidebar": true, "published": true, "skills": ["systems-design", "production-planning", "technical-specification"], "blocks": [{"id": "studio-desk-paragraph-0", "type": "text", "text": "Once the site existed, I wanted to be able to **keep working on it myself**. I did not want every new paragraph, image or project to turn into another development task. That is why I added the custom editor introduced above, Studio Desk."}, {"id": "studio-desk-paragraph-1", "type": "text", "text": "I think of it as **a personal Squarespace of sorts**, built around this portfolio’s structure. I can edit copy, upload media, add projects and arrange text, images, galleries, quotes and other supported blocks without editing the source files."}, {"id": "studio-desk-paragraph-2", "type": "text", "text": "The **live preview updates while I edit**, with desktop and mobile views and a light/dark switch. That helps me see how a choice works on the page instead of imagining the result from a form."}, {"id": "studio-desk-paragraph-3", "type": "text", "text": "I can change palettes, manage featured projects and connect **skills to the sections where I explain them**. The content relationships are editable alongside the writing, so the roles and project dots can develop with the portfolio."}, {"id": "studio-desk-paragraph-4", "type": "text", "text": "I can publish a project overview while **keeping its longer case study private** until it is ready. Building new interaction behaviours still requires code, but routine content and layout changes are handled in the editor."}, {"type": "gallery", "id": "editor-theme-comparison", "items": [{"type": "image", "id": "case-editor-light", "src": "assets/case-study/case-editor-light.jpg", "alt": "Editor palettes beside the light website preview.", "caption": "The custom editor with a live light-theme preview."}, {"type": "image", "id": "case-editor-dark", "src": "assets/case-study/case-editor-dark.jpg", "alt": "The same editor with dark website preview.", "caption": "Switching the preview to dark mode keeps editing in place."}]}, {"type": "image", "id": "studio-desk", "src": "assets/case-study/studio-desk.jpg", "alt": "Custom editor with content controls and page preview.", "caption": "Content and layout editing stay beside the page being edited."}], "subheading": "A personal site builder, tailored to this portfolio"}, {"id": "implementation", "heading": "Technical specification", "label": "Technical specification", "sidebar": true, "published": true, "skills": ["technical-specification", "scope-delivery"], "blocks": [{"id": "implementation-paragraph-0", "type": "text", "text": "The public site is a collection of **static HTML, CSS and JavaScript files on GitHub Pages**. The editor runs in the browser too, so I do not have to maintain a separate application server for day-to-day editing."}, {"id": "implementation-paragraph-1", "type": "text", "text": "The editor connects to the **GitHub API** to save draft content and write the public files when I publish. Draft storage and the published site are separate, which lets me prepare changes without immediately showing them to visitors."}, {"id": "implementation-paragraph-2", "type": "text", "text": "The preview and publication use **shared rendering code**, helping keep what I see while editing aligned with what gets published. Sections marked unpublished, and media referenced only by those sections, are left out of the public export."}, {"id": "implementation-paragraph-3", "type": "text", "text": "I can save backups and recover earlier versions. If another tab has saved a newer draft, the editor **detects the conflict instead of silently replacing it**, so I can decide which changes to keep."}, {"id": "implementation-paragraph-4", "type": "text", "text": "My work on this project has been the product direction, experience design, content structure, writing and repeated testing. **Implementation was AI-assisted**, including development, debugging and revisions to the site and editor."}, {"type": "image", "id": "case-editor-sections", "src": "assets/case-study/case-editor-sections.jpg", "alt": "Editor controls for publishing the write-up and selecting skill-dot destinations beside the public overview.", "caption": "A local demonstration of publication boundaries: the overview is visible while the write-up remains unpublished."}], "subheading": "Static hosting, browser editing and controlled publishing"}], "credits": [], "facts": [{"label": "My work", "value": "[Product direction](skills.html#skill-product-definition), [experience design](skills.html#skill-ui-ux), [information architecture](skills.html#skill-information-architecture), [writing](skills.html#skill-content-design) and [iterative testing](skills.html#skill-usability-iteration)"}, {"label": "Implementation", "value": "HTML, CSS and JavaScript · Browser-based editing · GitHub API · Static GitHub Pages publishing"}, {"label": "Project status", "value": "Under construction. Project overviews are available, this case study is published, and other project case studies are in progress."}], "introBlocks": [{"id": "portfolio-projectTitle", "type": "projectTitle"}, {"id": "portfolio-overview-screenshot", "type": "image", "src": "assets/case-study/home.jpg", "alt": "The portfolio homepage with its rotating introduction and two-sided portrait card.", "caption": "The live homepage, captured during development. The introduction links roles to the work behind them."}, {"id": "portfolio-projectTagline", "type": "projectTagline"}, {"id": "portfolio-projectSummary", "type": "projectSummary"}, {"id": "portfolio-facts", "type": "facts"}], "endBlocks": [{"id": "portfolio-endLinks", "type": "endLinks"}], "summaryDesignLabel": "Design", "summaryTechnicalLabel": "Technical", "summaryDesign": "I wanted one place for my games, films, artwork and other projects, with a clearer way to explain what I contributed to each of them. Here, you can follow a **role on the homepage to a skill**, then choose a project where I used it. Along the way, I wanted the website to feel personal and satisfying to use, while giving visitors control over its motion and navigation.", "summaryTechnical": "The portfolio runs on **GitHub Pages**, using HTML, CSS and JavaScript. I also added a **custom browser-based editor**, which I named Studio Desk, so I can change the content, arrange pages and publish updates from the same website. It uses the GitHub API to save private drafts and publish static files, with **no separate application server** for me to host."};
function applyHumanCase(data){if(data._humanCaseVersion)return;const p=data.projects.find(p=>p.id==='portfolio-studio-desk');if(p){for(const k of ['title','tagline','description','summary','summaryDesignLabel','summaryTechnicalLabel','summaryDesign','summaryTechnical','facts','sections'])p[k]=structuredClone(humanCase[k]);}for(const project of data.projects){for(const f of project.facts||[]){f.value=f.value.replace(/post-mortems?/gi,'case studies');if(f.overviewOnly&&f.label==='About this page')f.value='Case study coming soon. This overview introduces the project while I prepare the fuller write-up.';}}data._humanCaseVersion=1;}

const finalVisuals=[["portrait", "portrait-paragraph-1", {"id": "work-menu-detail", "type": "image", "src": "assets/case-study/work-menu-detail.jpg", "alt": "Work categories beside an Illustration panel showing six projects and an And more link.", "caption": "Six projects are visible beside the category list. And more opens the complete category."}], ["accessibility", "accessibility-paragraph-3", {"id": "responsive-comparison", "type": "image", "src": "assets/case-study/responsive-comparison.jpg", "alt": "The homepage at 1400 pixels wide beside the same page at 390 pixels wide.", "caption": "The same page at desktop and mobile widths. The card moves below the introduction while the name and navigation remain on one line. Roles vary independently."}]];
function applyFinalVisuals(data){if(data._finalVisualsVersion)return;const p=data.projects.find(p=>p.id==='portfolio-studio-desk');if(p)for(const [sid,after,b] of finalVisuals){const section=p.sections.find(s=>s.id===sid);if(!section||section.blocks.some(x=>x.id===b.id))continue;const index=section.blocks.findIndex(x=>x.id===after);section.blocks.splice(index<0?section.blocks.length:index+1,0,structuredClone(b));}data._finalVisualsVersion=1;}
